SELECT

FROM ${tableName} t
WHERE 1=1
 and t.big_id = #{query.bigId}
 and t.platenumber = #{query.platenumber}
 and t.sectioncode = #{query.sectioncode}
 and t.gantrycode = #{query.gantrycode}
 and t.snapshottime >= #{query.snapshottime}
 and t.snapshottime < #{query.applyTime2}
