SELECT

FROM ods_rt_szdn_snapshot_flow_view t
WHERE 1=1
 and t.big_id = #{bigId}
 and t.platenumber = #{platenumber}
 and t.sectioncode = #{sectioncode}
 and t.gantrycode = #{gantrycode}
 and t.snapshottime >= #{snapshottime}
 and t.snapshottime < #{applyTime2}
 and t.orgcode = #{orgcode}
ORDER BY t.snapshottime DESC

SELECT
    COUNT(*) as totalCount,
    sectioncode as sectionCode,
    COUNT(CASE WHEN sectioncode IS NOT NULL THEN 1 END) as sectionCount
FROM ${tableName} t
WHERE 1=1
 and t.platenumber = #{query.platenumber}
 and t.snapshottime >= #{query.snapshottime}
 and t.snapshottime < #{query.applyTime2}
GROUP BY sectioncode WITH ROLLUP
